mapper.select:
select o.*, r.remind_count, r.last_remind_time
from orders o
left join seller_reminders r on r.order_id = o.id
where o.user_id = #{userId}  and o.status = #{status} 
order by o.id desc limit #{offset}, #{size}

select count(*)
    from orders
    where user_id = #{userId}  and status = #{status}

select count(*) from orders o
                where exists (select 1 from order_items i where i.order_id = o.id and i.shop_id = #{shopId})
                  and o.status = #{status}

select * from orders
where user_id = #{userId} and pay_no = #{payNo}
order by id
